void MatMulHot(const float *a, const float *b, float *out, int n) {
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      float sum = 0.0F;
      for (int k = 0; k < n; ++k) sum += a[i * n + k] * b[k * n + j];
      out[i * n + j] = sum;
    }
  }
}

void conv2d(const float *input, const float *kernel, float *output, int width, int height) {
  for (int y = 1; y < height - 1; ++y) {
    for (int x = 1; x < width - 1; ++x) {
      float sum = 0.0F;
      for (int ky = -1; ky <= 1; ++ky) for (int kx = -1; kx <= 1; ++kx) {
        sum += input[(y + ky) * width + x + kx] * kernel[(ky + 1) * 3 + kx + 1];
      }
      output[y * width + x] = sum;
    }
  }
}

void reduce_sum(const float *tensor, float *output, int outer, int axis) {
  for (int row = 0; row < outer; ++row) {
    float sum = 0.0F;
    for (int i = 0; i < axis; ++i) sum += tensor[row * axis + i];
    output[row] = sum;
  }
}

