void PrefixSum(const int *input, int *output, size_t count) {
  if (count == 0) return;
  output[0] = input[0];
  for (size_t i = 1; i < count; ++i) output[i] = output[i - 1] + input[i];
}

Token ParseJsonToken(const char *text, size_t length) {
  size_t index = 0;
  while (index < length && std::isspace(text[index])) ++index;
  if (index == length) return Token::End();
  if (text[index] == '{') return Token::ObjectStart();
  if (text[index] == '[') return Token::ArrayStart();
  return ParseScalar(text + index, length - index);
}

