void depthwise_conv2d(const float *feature, const float *kernel, float *out,
    int width, int height, int channels) {
  for (int y = 1; y < height - 1; ++y) for (int x = 1; x < width - 1; ++x)
    for (int c = 0; c < channels; ++c) {
      float acc = 0.0F;
      for (int ky = -1; ky <= 1; ++ky) for (int kx = -1; kx <= 1; ++kx)
        acc += feature[((y + ky) * width + x + kx) * channels + c] * kernel[(ky + 1) * 3 + kx + 1];
      out[(y * width + x) * channels + c] = acc;
    }
}

void avg_pool(const float *image, float *pooled, int width, int height) {
  for (int y = 0; y < height / 2; ++y) for (int x = 0; x < width / 2; ++x) {
    float sum = 0.0F;
    for (int ky = 0; ky < 2; ++ky) for (int kx = 0; kx < 2; ++kx)
      sum += image[(y * 2 + ky) * width + x * 2 + kx];
    pooled[y * (width / 2) + x] = sum * 0.25F;
  }
}

void softmax(const float *tensor, float *probability, int batch, int classes) {
  for (int b = 0; b < batch; ++b) {
    float sum = 0.0F;
    for (int c = 0; c < classes; ++c) {
      float value = expf(tensor[b * classes + c]);
      probability[b * classes + c] = value;
      sum += value;
    }
    for (int c = 0; c < classes; ++c) probability[b * classes + c] /= sum;
  }
}

void layer_norm(const float *tensor, const float *scale, const float *bias,
    float *out, int rows, int cols) {
  for (int r = 0; r < rows; ++r) {
    float mean = 0.0F;
    for (int c = 0; c < cols; ++c) mean += tensor[r * cols + c];
    mean /= cols;
    float variance = 0.0F;
    for (int c = 0; c < cols; ++c) { float d = tensor[r * cols + c] - mean; variance += d * d; }
    for (int c = 0; c < cols; ++c) out[r * cols + c] = (tensor[r * cols + c] - mean) / sqrtf(variance / cols + 1e-5F) * scale[c] + bias[c];
  }
}

void ApplyContrastRgba(uint8_t *rgba, int pixelCount, float contrast) {
  for (int i = 0; i < pixelCount * 4; i += 4) {
    rgba[i] = Clamp((rgba[i] - 128.0F) * contrast + 128.0F);
    rgba[i + 1] = Clamp((rgba[i + 1] - 128.0F) * contrast + 128.0F);
    rgba[i + 2] = Clamp((rgba[i + 2] - 128.0F) * contrast + 128.0F);
  }
}

