Node *ParseJsonTree(TokenStream &stream) {
  if (stream.Peek() == Token::LBRACE) return ParseObject(stream);
  if (stream.Peek() == Token::LBRACKET) return ParseArray(stream);
  if (stream.Peek() == Token::STRING) return NewString(stream.Read());
  return NewNumber(stream.ReadNumber());
}

