void max_pool(const float *feature, float *out, int width, int height) {
  for (int y = 0; y < height / 2; ++y) for (int x = 0; x < width / 2; ++x) {
    float maximum = -FLT_MAX;
    for (int ky = 0; ky < 2; ++ky) for (int kx = 0; kx < 2; ++kx)
      maximum = std::max(maximum, feature[(y * 2 + ky) * width + x * 2 + kx]);
    out[y * (width / 2) + x] = maximum;
  }
}

void transpose(const float *tensor, float *out, int rows, int cols) {
  for (int r = 0; r < rows; ++r) for (int c = 0; c < cols; ++c)
    out[c * rows + r] = tensor[r * cols + c];
}

void resize_bilinear(const float *image, float *out, int inWidth, int inHeight,
    int outWidth, int outHeight) {
  for (int y = 0; y < outHeight; ++y) for (int x = 0; x < outWidth; ++x) {
    float fx = x * (inWidth - 1.0F) / (outWidth - 1.0F);
    float fy = y * (inHeight - 1.0F) / (outHeight - 1.0F);
    out[y * outWidth + x] = SampleBilinear(image, inWidth, inHeight, fx, fy);
  }
}

void fully_connected(const float *tensor, const float *weight, const float *bias,
    float *out, int inputSize, int outputSize) {
  for (int o = 0; o < outputSize; ++o) {
    float sum = bias[o];
    for (int i = 0; i < inputSize; ++i) sum += tensor[i] * weight[o * inputSize + i];
    out[o] = sum;
  }
}

