bool FindReachableNode(const Graph &graph, int start, int target) {
  std::queue<int> pending;
  std::unordered_set<int> visited;
  pending.push(start);
  while (!pending.empty()) {
    int node = pending.front(); pending.pop();
    if (node == target) return true;
    for (int next : graph.Neighbors(node)) if (visited.insert(next).second) pending.push(next);
  }
  return false;
}

