uint64_t EstimateArea(uint64_t samples, Random &random) {
  uint64_t inside = 0;
  for (uint64_t i = 0; i < samples; ++i) {
    float x = random.Next(); float y = random.Next();
    if (x * x + y * y <= 1.0F) ++inside;
  }
  return inside;
}

void AccumulateOffsets(const uint32_t *sizes, uint32_t *offsets, size_t count) {
  offsets[0] = 0;
  for (size_t i = 1; i < count; ++i) offsets[i] = offsets[i - 1] + sizes[i - 1];
}
